import json
from django.views import View
from django.http import JsonResponse, HttpResponseBadRequest, HttpResponseForbidden
from two_factor.plugins.phonenumber.models import PhoneDevice

class SMSDevicePhoneUpdateView(View):
    def post(self, request):
        if not request.user.is_authenticated:
            return HttpResponseForbidden("Authentication required")

        data = json.loads(request.body)
        device_id = data.get("device_id")
        new_number = data.get("phone_number")

        # Validate that the phone device belongs to the authenticated user
        updated = PhoneDevice.objects.filter(id=device_id, user=request.user).update(number=new_number)
        if not updated:
            return HttpResponseBadRequest("Invalid device ID")

        return JsonResponse({"status": "Phone number updated", "device_id": device_id})
